import json, urllib.request

TOKEN = open('/tmp/owner_verified_token.txt').read().strip()
BASE = 'https://api.ivxholding.com'

def call(action, input_data=None):
    payload = {'action': action, 'input': input_data or {}}
    req = urllib.request.Request(f'{BASE}/api/ivx/developer-deploy/action',
        data=json.dumps(payload).encode(),
        headers={'Content-Type': 'application/json', 'Authorization': f'Bearer {TOKEN}'},
        method='POST')
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        return e.code, json.loads(e.read().decode())

status, data = call('get_ses_account_status')
print(f'get_ses_account_status: HTTP {status}')
print(json.dumps(data, indent=2, default=str)[:2000])
PYEOF

